o2.xApplication.CloudDocument.FavExplorer=new Class({Extends:o2.xApplication.CloudDocument.Explorer,initData:function(){this.srv.execute("queryFavByPage",{page:this.options.page,pageSize:this.options.pageSize},function(e){e.dataList.each(function(e){e.name=e.fileName}.bind(this)),this.dataList=e.dataList,this._initData()}.bind(this))},loadBread:function(){this._loadBread("星标文档")},_loadBread:function(e){this.breadNode.empty();var t=new Element("span").inject(this.breadNode);new Element("span.ant-breadcrumb-link").inject(t).set("html",'<a href="javascript:;">'+e+"</a>")}}),o2.xApplication.CloudDocument.FavExplorer.View=new Class({Extends:o2.xApplication.CloudDocument.Explorer.View,unStarMulti:function(){this.getSelected().each(function(e){this.srv.execute("deleteFav",{documentId:e.id},function(e){}.bind(this))}.bind(this)),this.wi.message("success","取消成功"),this.reload(),this.cancelAll()}}),o2.xApplication.CloudDocument.FavExplorer.Document=new Class({Extends:o2.xApplication.CloudDocument.Explorer.Document});